function.body:
RETURN EXISTS (
  SELECT 1 FROM public.users 
  WHERE id = auth.uid() AND role = 'admin'
);

INSERT INTO public.users (id, email, phone, name, created_at, updated_at)
VALUES (
  NEW.id,
  NEW.email,
  NEW.phone,
  COALESCE(NEW.raw_user_meta_data->>'name', 'User'),
  NOW(),
  NOW()
);
RETURN NEW;

UPDATE lawyers SET
  rating = (SELECT AVG(rating) FROM reviews WHERE lawyer_id = NEW.lawyer_id),
  total_reviews = (SELECT COUNT(*) FROM reviews WHERE lawyer_id = NEW.lawyer_id),
  updated_at = NOW()
WHERE id = NEW.lawyer_id;
RETURN NEW;

validation_middleware.error_response:
{
  "success": false,
  "error": {
    "code": "VALIDATION_ERROR",
    "message": "Invalid request data",
    "details": [
      { "field": "email", "message": "Invalid email format", "code": "invalid_string" },
      { "field": "phone", "message": "Invalid Indian phone number", "code": "invalid_string" }
    ]
  }
}

